const upstreamLogoutSessionSubjects = `-- name: UpstreamLogoutSessionSubjects :many
SELECT s.id,s.user_id FROM sessions s JOIN upstream_sessions u ON u.session_id=s.id WHERE u.provider_id=$1 AND u.provider_revision=$2 AND u.token_issued_at <= $3
AND ($4::text='' OR u.sid=$4) AND ($5::text='' OR u.subject=$5) ORDER BY s.id
`

type UpstreamLogoutSessionSubjectsParams struct {
	ProviderID       ids.UpstreamProviderID `json:"provider_id"`
	ProviderRevision int64                  `json:"provider_revision"`
	IssuedAt         int64                  `json:"issued_at"`
	Sid              string                 `json:"sid"`
	Subject          string                 `json:"subject"`
}

type UpstreamLogoutSessionSubjectsRow struct {
	ID     ids.SessionID `json:"id"`
	UserID ids.UserID    `json:"user_id"`
}

func (q *Queries) UpstreamLogoutSessionSubjects(ctx context.Context, arg UpstreamLogoutSessionSubjectsParams) ([]UpstreamLogoutSessionSubjectsRow, error) {
	rows, err := q.db.Query(ctx, upstreamLogoutSessionSubjects,
		arg.ProviderID,
		arg.ProviderRevision,
		arg.IssuedAt,
		arg.Sid,
		arg.Subject,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UpstreamLogoutSessionSubjectsRow{}
	for rows.Next() {
		var i UpstreamLogoutSessionSubjectsRow
		if err := rows.Scan(&i.ID, &i.UserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

